def _wo006_sup_stray_copy(destination):
    def mutate(case):
        source = case / _WO006_SUP_REL
        target = (case / "docs" / "work-orders" / destination
                  / source.name)
        target.write_text(source.read_text(encoding="utf-8"),
                          encoding="utf-8")
    return mutate


